  { id: "NC-C20", status: "confirmed", statement: "CE is eight hours annually: four-hour Update plus four-hour elective; the Update course is not self-paced distance.", sourceIds: ["NC-STAT-93A-38.5", "NC-RULE-58H-.0404", "NC-RULE-58H-.0205-.0206"], pinpoint: "G.S. 93A-38.5(a)-(b); 58H .0403(g), .0404", evidence: "Self-paced delivery is suitable for electives, not the Commission-created Update course.", reliedOnBy: ["product-roadmap"] }
